p=Path('packages/db/src/security.ts');s=p.read_text();s=s.replace("export function hash(value:unknown){return createHash('sha256').update(JSON.stringify(value)).digest('hex');}","function canonical(value:unknown):unknown{if(value instanceof Date)return value.toISOString();if(Array.isArray(value))return value.map(canonical);if(value&&typeof value==='object'){const record=value as Record<string,unknown>;return Object.fromEntries(Object.keys(record).filter(k=>record[k]!==undefined).sort().map(k=>[k,canonical(record[k])]));}return value;}\nexport function hash(value:unknown){return createHash('sha256').update(JSON.stringify(canonical(value))).digest('hex');}");p.write_text(s)
